import fs from "fs/promises";
import path from "path";
import crypto from "crypto";

/**
 * Stores uploaded media files on disk under random keys.
 */
export class FileStorage {
	constructor(private readonly root: string) {}

	private resolve(key: string): string {
		// keys are generated by us, but never trust them blindly
		if (!/^[a-f0-9-]+$/.test(key)) throw new Error("Invalid storage key");
		return path.join(this.root, key);
	}

	public async save(data: Buffer): Promise<string> {
		await fs.mkdir(this.root, { recursive: true });
		const key = crypto.randomUUID();
		await fs.writeFile(this.resolve(key), data);
		return key;
	}

	public async read(key: string): Promise<Buffer> {
		return fs.readFile(this.resolve(key));
	}

	public async remove(key: string): Promise<void> {
		await fs.rm(this.resolve(key), { force: true });
	}
}
